<?php
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
require_once __DIR__.'/../Config/Database.php';$db=(new Database())->connect();
$db->exec('CREATE TABLE IF NOT EXISTS configuracion_credito_cliente (cliente_id BIGINT UNSIGNED PRIMARY KEY,habilitado TINYINT NOT NULL DEFAULT 0,limite DECIMAL(14,2) NOT NULL DEFAULT 0,dias SMALLINT UNSIGNED NOT NULL DEFAULT 30,FOREIGN KEY(cliente_id) REFERENCES clientes(id) ON DELETE CASCADE) ENGINE=InnoDB');
$db->exec('CREATE TABLE IF NOT EXISTS creditos_venta (venta_id BIGINT UNSIGNED PRIMARY KEY,cliente_id BIGINT UNSIGNED NOT NULL,monto_original DECIMAL(14,2) NOT NULL,vence DATE NOT NULL,FOREIGN KEY(venta_id) REFERENCES ventas(id) ON DELETE CASCADE,FOREIGN KEY(cliente_id) REFERENCES clientes(id),KEY ix_credito_cliente(cliente_id)) ENGINE=InnoDB');
$db->exec('CREATE TABLE IF NOT EXISTS abonos_cliente (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,folio VARCHAR(30) NOT NULL UNIQUE,venta_id BIGINT UNSIGNED NOT NULL,cliente_id BIGINT UNSIGNED NOT NULL,turno_id BIGINT UNSIGNED NOT NULL,usuario_id BIGINT UNSIGNED NOT NULL,metodo_pago_id BIGINT UNSIGNED NOT NULL,monto DECIMAL(14,2) NOT NULL,recibido DECIMAL(14,2) NULL,cambio DECIMAL(14,2) NOT NULL DEFAULT 0,referencia VARCHAR(100) NULL,clave CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,huella CHAR(64) NOT NULL,datos JSON NOT NULL,creado_en TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(venta_id) REFERENCES ventas(id) ON DELETE CASCADE,FOREIGN KEY(cliente_id) REFERENCES clientes(id),FOREIGN KEY(turno_id) REFERENCES turnos_caja(id),FOREIGN KEY(usuario_id) REFERENCES usuarios(id),FOREIGN KEY(metodo_pago_id) REFERENCES metodos_pago(id),UNIQUE KEY uq_abono_solicitud(usuario_id,clave),KEY ix_abono_turno(turno_id),KEY ix_abono_fecha(creado_en)) ENGINE=InnoDB');
$cols=$db->query('SHOW COLUMNS FROM pagos_venta')->fetchAll(PDO::FETCH_COLUMN);if(!in_array('abono_id',$cols,true))$db->exec('ALTER TABLE pagos_venta ADD COLUMN abono_id BIGINT UNSIGNED NULL,ADD UNIQUE KEY uq_pago_abono(abono_id),ADD FOREIGN KEY(abono_id) REFERENCES abonos_cliente(id) ON DELETE CASCADE');
if(!(int)$db->query("SELECT COUNT(*) FROM metodos_pago WHERE tipo='credito'")->fetchColumn())$db->exec("INSERT INTO metodos_pago(nombre,tipo,activo) VALUES ('Crédito de clientes','credito',1)");
echo "Crédito y abonos preparados.",PHP_EOL;
